    tip1: 'ਸੂਚੀ ਵਿੱਚੋਂ ਕੋਈ ਉਦਾਹਰਨ ਚੁਣੋ ਅਤੇ ▶ ਚਲਾਓ ਦਬਾਓ। ਫਿਰ ਕੋਈ ਸੰਖਿਆ ਜਾਂ ਸ਼ਬਦ ਬਦਲ ਕੇ ਦੁਬਾਰਾ ਚਲਾਓ। ਚਲਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਅੰਦਾਜ਼ਾ ਲਗਾਓ ਕਿ ਆਉਟਪੁਟ ਕੀ ਆਵੇਗਾ!',
    tip2: 'Ctrl + Enter ਨਾਲ ਕੋਡ ਚੱਲਦਾ ਹੈ। Tab ਨਾਲ 4 ਸਪੇਸ ਜੁੜਦੀਆਂ ਹਨ ਅਤੇ Shift + Tab ਨਾਲ ਹਟਦੀਆਂ ਹਨ। : ਉੱਤੇ ਖ਼ਤਮ ਹੋਣ ਵਾਲੀ ਲਾਈਨ ਤੋਂ ਬਾਅਦ ਅਗਲੀ ਲਾਈਨ ਆਪਣੇ-ਆਪ ਅੰਦਰ ਖਿਸਕ ਜਾਂਦੀ ਹੈ। ਫ਼ੋਨ ਉੱਤੇ ਐਡੀਟਰ ਹੇਠਾਂ ਵਾਲੇ ਛੋਟੇ ਬਟਨ ਵਰਤੋ।',
    tip3: 'ਜਦੋਂ ਪ੍ਰੋਗਰਾਮ input() ਬੁਲਾਉਂਦਾ ਹੈ ਤਾਂ ਸਕ੍ਰੀਨ ਦੇ ਉੱਪਰ ਇੱਕ ਛੋਟਾ ਬਾਕਸ ਖੁੱਲ੍ਹਦਾ ਹੈ। ਜਵਾਬ ਲਿਖੋ ਅਤੇ OK ਦਬਾਓ।',
    tip4: 'ਲਾਲ ਲਿਖਤ ਐਰਰ ਹੈ। ਉਸਦੀ ਆਖ਼ਰੀ ਲਾਈਨ ਅਤੇ ਹੇਠਾਂ ਦਿੱਤੀ ਪੀਲੀ ਸਲਾਹ ਪੜ੍ਹੋ, ਫਿਰ “ਲਾਈਨ ਦਿਖਾਓ” ਦਬਾ ਕੇ ਗਲਤੀ ਤੱਕ ਪਹੁੰਚੋ।',
    tip5: 'ਅਧਿਆਪਕ: ਪ੍ਰੋਗਰਾਮ ਲਿਖੋ, “ਲਿੰਕ ਸਾਂਝਾ ਕਰੋ” ਦਬਾਓ ਅਤੇ ਜਮਾਤ ਦੇ WhatsApp ਗਰੁੱਪ ਵਿੱਚ ਭੇਜੋ। ਵਿਦਿਆਰਥੀ ਆਪਣੇ ਫ਼ੋਨ ਉੱਤੇ ਉਹੀ ਕੋਡ ਖੋਲ੍ਹ ਲੈਣਗੇ।',
    tip6: 'ਜਮਾਤ ਦੀ ਗਤੀਵਿਧੀ, ਬੱਗ ਲੱਭੋ: ਬੋਰਡ ਉੱਤੇ ਇੱਕ ਲੁਕੀ ਗਲਤੀ ਵਾਲੀ ਉਦਾਹਰਨ ਦਿਖਾਓ (ਰਹਿ ਗਿਆ :, ਗਲਤ ਇੰਡੈਂਟ, ਗਲਤ ਸਪੈਲਿੰਗ)। ਜੋੜੀਆਂ ਐਰਰ ਪੜ੍ਹ ਕੇ ਗਲਤੀ ਠੀਕ ਕਰਨ ਅਤੇ ਕਾਰਨ ਸਮਝਾਉਣ। ਸਹੀ ਆਉਟਪੁਟ ਲਿਆਉਣ ਵਾਲੀ ਪਹਿਲੀ ਜੋੜੀ ਜਿੱਤੇਗੀ।',
    tip7: 'pandas ਅਤੇ matplotlib (ਜਮਾਤ 12 IP) ਪਹਿਲੀ ਵਾਰ ਵਰਤਣ ਤੇ ਡਾਊਨਲੋਡ ਹੁੰਦੇ ਹਨ। ਪ੍ਰੈਕਟੀਕਲ ਫ਼ਾਈਲ ਲਈ ਚਾਰਟ ਦੀ ਤਸਵੀਰ ਡਾਊਨਲੋਡ ਕਰ ਲਓ।',
    inside_head: 'ਅੰਦਰ ਕੀ ਹੋ ਰਿਹਾ ਹੈ?',
    inside1: 'ਇਹ ਪੇਜ Pyodide ਡਾਊਨਲੋਡ ਕਰਦਾ ਹੈ: ਅਸਲੀ Python (CPython 3.12), ਜਿਸਨੂੰ WebAssembly ਵਿੱਚ ਬਦਲਿਆ ਗਿਆ ਹੈ — ਅਜਿਹਾ ਫ਼ਾਰਮੈਟ ਜਿਸਨੂੰ ਹਰ ਨਵਾਂ ਬ੍ਰਾਊਜ਼ਰ ਚਲਾ ਸਕਦਾ ਹੈ। ਪਹਿਲੀ ਵਾਰ ਇਹ ਲਗਭਗ 10 MB ਹੈ; ਫਿਰ ਬ੍ਰਾਊਜ਼ਰ ਇਸਦੀ ਕਾਪੀ ਰੱਖ ਲੈਂਦਾ ਹੈ।',
    inside2: 'ਤੁਹਾਡਾ ਕੋਡ ਤੁਹਾਡੇ ਆਪਣੇ ਡਿਵਾਈਸ ਉੱਤੇ, ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਅੰਦਰ ਚੱਲਦਾ ਹੈ। ਕੁਝ ਵੀ ਸਰਵਰ ਨੂੰ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ, ਅਤੇ ਨਾ ਕੋਈ ਖਾਤਾ ਚਾਹੀਦਾ ਹੈ ਨਾ ਇੰਸਟਾਲ।',
    inside3: 'Python ਇਸੇ ਪੇਜ ਦੇ ਅੰਦਰ ਚੱਲਦਾ ਹੈ, ਇਸ ਲਈ ਕਦੇ ਨਾ ਰੁਕਣ ਵਾਲਾ ਲੂਪ ਪੇਜ ਨੂੰ ਅਟਕਾ ਸਕਦਾ ਹੈ। ਇਸੇ ਲਈ ਐਪ ਹਰ ਕੁਝ ਸਕਿੰਟਾਂ ਬਾਅਦ ਪ੍ਰੋਗਰਾਮ ਜਾਂਚਦੀ ਹੈ ਅਤੇ ਪੁੱਛਦੀ ਹੈ ਕਿ ਉਸਨੂੰ ਰੋਕਣਾ ਹੈ ਜਾਂ ਨਹੀਂ।',
    inside4: 'ਜ਼ਿਆਦਾਤਰ ਆਮ ਮੋਡਿਊਲ ਚੱਲਦੇ ਹਨ (math, random, statistics, csv, datetime…)। turtle ਅਤੇ tkinter ਨੂੰ ਡੈਸਕਟਾਪ ਵਿੰਡੋ ਚਾਹੀਦੀ ਹੈ, ਇਸ ਲਈ ਉਹ ਇੱਥੇ ਨਹੀਂ ਚੱਲਦੇ। ਤੁਹਾਡੀਆਂ ਬਣਾਈਆਂ ਫ਼ਾਈਲਾਂ ਸਿਰਫ਼ ਬ੍ਰਾਊਜ਼ਰ ਦੀ ਮੈਮਰੀ ਵਿੱਚ ਰਹਿੰਦੀਆਂ ਹਨ।'
