    grp_12ip: 'ക്ലാസ് 12 · ഇൻഫർമാറ്റിക്സ് പ്രാക്ടീസസ്',
    ex_hello: 'ഹലോയും വേരിയബിളുകളും', exn_hello: 'print(), വേരിയബിളുകൾ, ഡാറ്റ ടൈപ്പുകൾ, f-string.',
