    ex_ifelse: 'if–elif–else: CBSE ഗ്രേഡ്', exn_ifelse: 'if, elif, else ഉപയോഗിച്ച് മാർക്കിൽ നിന്ന് ഗ്രേഡ് കണ്ടെത്തൽ.',
    ex_loops: 'for, while ലൂപ്പുകൾ', exn_loops: 'for ഉപയോഗിച്ച് ഗുണനപ്പട്ടിക, while ഉപയോഗിച്ച് അക്കങ്ങളുടെ തുക, range().',
    ex_patterns: 'നക്ഷത്ര, സംഖ്യാ പാറ്റേണുകൾ', exn_patterns: 'ലൂപ്പിനുള്ളിൽ ലൂപ്പ് ഉപയോഗിച്ച് പിരമിഡും ത്രികോണങ്ങളും.',
    ex_strings: 'സ്ട്രിംഗ് മെത്തേഡുകൾ', exn_strings: 'upper(), split(), find(), replace(), സ്ലൈസിംഗ്, സ്വരാക്ഷരങ്ങളുടെ എണ്ണം, പാലിൻഡ്രോം.',
    ex_lists: 'ലിസ്റ്റും ലിസ്റ്റ് മെത്തേഡുകളും', exn_lists: 'append(), insert(), pop(), sort(), max(), sum(), സ്ലൈസിംഗ്.',
    ex_tuples: 'ട്യൂപ്പിളുകൾ', exn_tuples: 'ട്യൂപ്പിൾ മാറ്റാൻ കഴിയില്ല: ഇൻഡക്സ്, അൺപാക്കിംഗ്, പരസ്പരം മാറ്റൽ, count().',
    ex_dicts: 'ഡിക്ഷണറി: വിദ്യാർത്ഥികളുടെ മാർക്ക്', exn_dicts: 'കീയും വാല്യുവും: ചേർക്കൽ, മാറ്റൽ, items() ലൂപ്പ്, get(), ടോപ്പറെ കണ്ടെത്തൽ.',
    ex_math: 'math മൊഡ്യൂൾ', exn_math: 'sqrt(), pi, ceil(), floor(), factorial(), gcd(), ത്രികോണമിതി.',
    ex_random: 'random മൊഡ്യൂൾ: പകിട', exn_random: 'randint() ഉപയോഗിച്ച് പകിട 600 തവണ ഉരുട്ടി ഓരോ മുഖവും എണ്ണൽ.',
    ex_functions: 'ഫംഗ്ഷനുകളും ഡിഫോൾട്ട് ആർഗ്യുമെന്റുകളും', exn_functions: 'def, return, ഡിഫോൾട്ട്, കീവേഡ് ആർഗ്യുമെന്റുകൾ, ലോക്കൽ, ഗ്ലോബൽ വേരിയബിളുകൾ.',
    ex_recursion: 'റിക്കർഷൻ: ഫാക്ടോറിയൽ', exn_recursion: 'സ്വയം വിളിക്കുന്ന ഫംഗ്ഷൻ, ബേസ് കേസോടെ: ഫാക്ടോറിയൽ, ഫിബൊണാച്ചി, അക്കങ്ങളുടെ തുക.',
    ex_exceptions: 'എക്സെപ്ഷൻ ഹാൻഡ്ലിംഗ്', exn_exceptions: 'try, except, else, finally പ്രോഗ്രാം ക്രാഷ് ആകാതെ കാക്കുന്നു.',
    ex_files: 'ടെക്സ്റ്റ്, CSV ഫയലുകൾ', exn_files: 'ഫയൽ എഴുതൽ, കൂട്ടിച്ചേർക്കൽ, വായിക്കൽ, പിന്നെ csv മൊഡ്യൂൾ. ഫയലുകൾ ബ്രൗസറിന്റെ മെമ്മറിയിലാണ്.',
    ex_text: 'ടെക്സ്റ്റ് പ്രോസസ്സിംഗ് (ഫയൽ ഇല്ലാതെ)', exn_text: 'വരികൾ, വാക്കുകൾ, വാക്യങ്ങൾ എണ്ണി, കൂടുതൽ വരുന്ന വാക്കുകൾ കണ്ടെത്തൽ.',
